import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [formData, setFormData] = useState({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' });
  const [searchQuery, setSearchQuery] = useState('');

  const fetchStudents = () => {
    axios.get('http://localhost:8081/api/view-students')
      .then(res => setStudents(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchStudents(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if(!formData.subjects) { alert("Please select at least one subject!"); return; }

    if (isEditing) {
      axios.put(`http://localhost:8081/api/update-student/${editId}`, formData).then(res => {
          fetchStudents(); resetForm(); alert("✅ Student Updated!");
      });
    } else {
      axios.post('http://localhost:8081/api/add-student', formData).then(res => {
          fetchStudents(); resetForm(); alert("✅ Student Added!");
      });
    }
  };

  const handleDelete = (id) => {
    if(window.confirm("Delete this student?")) {
      axios.delete(`http://localhost:8081/api/delete-student/${id}`).then(res => { fetchStudents(); });
    }
  };

  const handleEdit = (student) => {
    setIsEditing(true); setEditId(student.id);
    setFormData({ name: student.name, username: student.username || '', grade: student.grade, subjects: student.subjects, phone_number: student.phone_number, address: student.address, password: student.password });
    setShowForm(true);
  };

  const resetForm = () => {
    setShowForm(false); setIsEditing(false); setEditId(null);
    setFormData({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' });
  };

  const handleSubjectChange = (subject, isChecked) => {
    let currentSubjects = formData.subjects ? formData.subjects.split(', ') : [];
    if (isChecked) currentSubjects.push(subject); else currentSubjects = currentSubjects.filter(s => s !== subject);
    setFormData({ ...formData, subjects: currentSubjects.join(', ') });
  };

  const filteredStudents = [...students].reverse().filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()) || s.username?.toLowerCase().includes(searchQuery.toLowerCase()));
  const availableSubjects = ['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'History'];

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}>
        <h2 style={{ margin: 0, color: '#1e293b' }}>🧑‍🎓 Manage Students</h2>
        <div style={{ display: 'flex', gap: '15px' }}>
          <input type="text" placeholder="Search Students..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1' }} />
          <button onClick={() => { resetForm(); setShowForm(true); }} style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Register Student</button>
        </div>
      </div>

      <div style={{ backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '900px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>No.</th>
              <th style={thStyle}>Full Name</th>
              <th style={thStyle}>Username</th>
              <th style={thStyle}>Grade</th>
              <th style={thStyle}>Subjects</th>
              <th style={thStyle}>Telephone</th>
              <th style={thStyle}>Address</th>
              <th style={{...thStyle, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredStudents.map((s, index) => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...tdStyle, fontWeight: 'bold'}}>{index + 1}</td>
                <td style={{...tdStyle, color: '#15803d', fontWeight: 'bold'}}>{s.name}</td>
                <td style={tdStyle}>{s.username || '-'}</td>
                <td style={tdStyle}><span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '4px', fontSize: '12px', fontWeight: 'bold' }}>{s.grade}</span></td>
                <td style={{...tdStyle, fontSize: '13px'}}>{s.subjects}</td>
                <td style={tdStyle}>{s.phone_number}</td>
                <td style={tdStyle}>{s.address || '-'}</td>
                <td style={{...tdStyle, textAlign: 'center'}}>
                  <button onClick={() => handleEdit(s)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' }}>✏️</button>
                  <button onClick={() => handleDelete(s.id)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ margin: '0 0 20px 0' }}>{isEditing ? '✏️ Edit Student' : '➕ Register Student'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Username (For Login)" value={formData.username} onChange={(e) => setFormData({...formData, username: e.target.value})} required style={inputStyle} />
              <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
                {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026'].map(g => <option key={g} value={g}>{g}</option>)}
              </select>
              <div style={{ padding: '15px', border: '1px solid #cbd5e1', borderRadius: '8px' }}>
                <p style={{ margin: '0 0 10px 0', fontSize: '13px', fontWeight: 'bold' }}>Select Subjects:</p>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                  {availableSubjects.map(sub => (
                    <label key={sub} style={{ fontSize: '13px', display: 'flex', alignItems: 'center', gap: '5px' }}>
                      <input type="checkbox" checked={formData.subjects.includes(sub)} onChange={(e) => handleSubjectChange(sub, e.target.checked)} /> {sub}
                    </label>
                  ))}
                </div>
              </div>
              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Address" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px 20px', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', borderRadius: '8px', cursor: 'pointer' }}>Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const inputStyle = { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '14px', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', color: '#475569', fontSize: '13px', textAlign: 'left' };
const tdStyle = { padding: '15px', fontSize: '13px', color: '#1e293b' };
